// 1. Check for NULL pointers
if ((request == NULL) || (field == NULL) || (parallel == NULL) || 
    (perpendicular == NULL) || (fraction == NULL)) {
    return ADCS_E_NULL;
}

// 2. Check for non-finite inputs
if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    *parallel = (adcs_vec3_t){0.0, 0.0, 0.0};
    *perpendicular = (adcs_vec3_t){0.0, 0.0, 0.0};
    *fraction = 0.0;
    return ADCS_E_DEGENERATE;
}

// 3. Compute field norm and check for degeneracy
double norm_field = adcs_vec3_norm(field);
if (norm_field <= ADCS_EPS_NORM) {
    *parallel = (adcs_vec3_t){0.0, 0.0, 0.0};
    *perpendicular = (adcs_vec3_t){0.0, 0.0, 0.0};
    *fraction = 0.0;
    return ADCS_E_DEGENERATE;
}

// 4. Normalize the magnetic field to get unit vector u
adcs_vec3_t u = adcs_vec3_scale(field, 1.0 / norm_field);

// 5. Compute parallel component: (request . u) * u
double dot_product = adcs_vec3_dot(request, &u);
*parallel = adcs_vec3_scale(&u, dot_product);

// 6. Compute perpendicular component: request - parallel
*perpendicular = adcs_vec3_sub(request, parallel);

// 7. Compute controllable fraction
double norm_request = adcs_vec3_norm(request);

// Handle zero request case
if (norm_request <= ADCS_EPS_NORM) {
    *fraction = 0.0;
} else {
    double norm_perp = adcs_vec3_norm(perpendicular);
    *fraction = norm_perp / norm_request;
}

return ADCS_OK;

